mapper.select:
SELECT c.id  WHERE u.id = #{actor} AND 

AND c.id < #{afterId}
ORDER BY c.id DESC LIMIT #{limit}

WITH exact_hits AS (
    SELECT c.id, 0 AS tier, 0.0::double precision AS score 
    WHERE u.id = #{actor} AND r.normalized_questions_json @> jsonb_build_array(CAST(#{normalizedQuery} AS text))
        AND  
    ORDER BY c.id LIMIT #{limit}
), question_hits AS (
    SELECT c.id, 1 AS tier, pdb.score(r.id) AS score 
    WHERE u.id = #{actor} AND r.question_text ||| #{query}
        AND  
    ORDER BY pdb.score(r.id) DESC, c.id LIMIT #{limit}
), answer_hits AS (
    SELECT c.id, 2 AS tier, pdb.score(r.id) AS score 
    WHERE u.id = #{actor} AND r.answer ||| #{query}
        AND  
    ORDER BY pdb.score(r.id) DESC, c.id LIMIT #{limit}
), combined AS (
    SELECT * FROM exact_hits UNION ALL SELECT * FROM question_hits UNION ALL SELECT * FROM answer_hits
), deduplicated AS (
    SELECT DISTINCT ON (id) id, tier, score FROM combined ORDER BY id, tier, score DESC
) SELECT id FROM deduplicated ORDER BY tier, score DESC, id LIMIT #{limit}

SELECT EXISTS (SELECT 1  WHERE c.id = #{cardId}
    AND  AND  AND 
    AND  AND u.id <> #{submittedBy}
    AND NOT EXISTS (SELECT 1 FROM kb_answer_card_contributor ac WHERE ac.branch_id = #{branchId} AND ac.user_id = u.id))

SELECT u.id AS user_id, u.display_name  WHERE c.id = #{cardId}
    AND  AND  AND 
    AND  AND u.display_name LIKE #{namePattern} ESCAPE '\'
AND u.id > #{afterId}
ORDER BY u.id LIMIT #{limit}

SELECT c.id FROM kb_answer_card c CROSS JOIN sys_user u JOIN sys_dept dept ON dept.id = u.dept_id
WHERE u.id = #{actor} AND  AND 

AND c.id < #{afterId}
ORDER BY c.id DESC LIMIT #{limit}

SELECT r.id FROM kb_answer_card c JOIN kb_answer_card_revision r ON r.card_id = c.id
CROSS JOIN sys_user u JOIN sys_dept dept ON dept.id = u.dept_id
WHERE u.id = #{actor} AND c.id = #{cardId} AND  AND 
    AND (() OR ()) AND 
AND r.id < #{afterId}
ORDER BY r.id DESC LIMIT #{limit}

SELECT ar.id FROM kb_answer_card c JOIN kb_answer_card_revision r ON r.card_id = c.id
JOIN kb_answer_card_review ar ON ar.card_id = c.id AND ar.revision_id = r.id
CROSS JOIN sys_user u JOIN sys_dept dept ON dept.id = u.dept_id
WHERE u.id = #{actor} AND c.id = #{cardId} AND  AND 
    AND (() OR ()) AND 
AND r.id = #{revisionId}
AND ar.id < #{afterId}
ORDER BY ar.id DESC LIMIT #{limit}
